// Builds the source images @capacitor/assets turns into every iOS and Android icon and splash size.
//   npm run assets   (runs this, then capacitor-assets generate)
// Inputs are the brand kit's own exports (brand/png, generated by brand/build.mjs), so the app icon matches
// src/app/apple-icon.png: the mark on the site's dark background (#0a0a0a).
import sharp from "sharp";
import { mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const MOBILE = path.resolve(HERE, "..");
const BRAND = path.resolve(MOBILE, "../brand/png");
const OUT = path.join(MOBILE, "assets");
mkdirSync(OUT, { recursive: true });

const DARK = "#0a0a0a";
const LIGHT = "#f6f5f1";
const CLEAR = { r: 0, g: 0, b: 0, alpha: 0 };
const mark = path.join(BRAND, "mark/pockett-mark-dark-1024.png");

/** `src` scaled to `fraction` of a `size` square, centred on `background` (transparent when null). */
async function onCanvas(src, size, fraction, background, out) {
  const inner = Math.round(size * fraction);
  const img = await sharp(src).resize(inner, inner, { fit: "contain", background: CLEAR }).toBuffer();
  await sharp({ create: { width: size, height: size, channels: 4, background: background ?? CLEAR } })
    .composite([{ input: img, gravity: "center" }])
    .png()
    .toFile(path.join(OUT, out));
}

// iOS (and the legacy Android icon): a full-bleed square, the system rounds the corners
await onCanvas(mark, 1024, 0.64, DARK, "icon-only.png");
// Android adaptive icon: capacitor-assets insets the foreground by 16.7% a side, so the mark ends up at 40% of the
// 108dp icon, small enough that its corners stay inside the launcher's circle mask. The background is the brand dark.
await onCanvas(mark, 1024, 0.6, null, "icon-foreground.png");
await sharp({ create: { width: 1024, height: 1024, channels: 4, background: DARK } }).png().toFile(path.join(OUT, "icon-background.png"));
// Splash: the stacked lockup, centred, in each theme
await onCanvas(path.join(BRAND, "lockup-stacked/pockett-lockup-stacked-light-1024.png"), 2732, 0.22, LIGHT, "splash.png");
await onCanvas(path.join(BRAND, "lockup-stacked/pockett-lockup-stacked-dark-1024.png"), 2732, 0.22, DARK, "splash-dark.png");
console.log("wrote", OUT);
